await captchaResponse
const inputDetails = await page.locator('input').evaluateAll(inputs => inputs.map(input => ({
  type: input.type,
  placeholder: input.placeholder,
  visible: input.getClientRects().length > 0,
})))
const username = page.getByPlaceholder('请输入用户名/身份证号码/手机号码')
const password = page.getByPlaceholder('请输入密码')
if (await username.count()) await username.first().fill('visual-user')
if (await password.count()) await password.first().fill('visual-password')
if (!(await username.count()) || !(await password.count())) {
  const visibleInputs = page.locator('input:visible')
  if (await visibleInputs.count() < 2) throw new Error(`Login inputs unavailable: ${JSON.stringify(inputDetails)}`)
  await visibleInputs.nth(0).fill('visual-user')
  await visibleInputs.nth(1).fill('visual-password')
}
const agreement = page.locator('.login-agreement')
